func healRouteMatchesEntry(route *metadata.ResolvedSourceRoute, entry *source.TableRegistry) bool {
	if route == nil || route.TableConfig == nil || entry == nil {
		return false
	}
	if entry.ID > 0 && route.TableConfig.ID > 0 && route.TableConfig.ID != entry.ID {
		return false
	}
	if strings.TrimSpace(entry.SourceDB) != "" && !strings.EqualFold(strings.TrimSpace(route.TableConfig.SourceDB), strings.TrimSpace(entry.SourceDB)) {
		return false
	}
	if strings.TrimSpace(entry.SourceTable) != "" && !strings.EqualFold(strings.TrimSpace(route.TableConfig.SourceTable), strings.TrimSpace(entry.SourceTable)) {
		return false
	}
	if strings.TrimSpace(entry.ShadowSchema) != "" && !strings.EqualFold(strings.TrimSpace(route.TableConfig.ShadowSchema), strings.TrimSpace(entry.ShadowSchema)) {
		return false
	}
	return true
}

